#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

# The palette is the wizard library's, whole. `RED` has no caller in these stages, and it stays
# anyway rather than making this copy diverge from the template every wizard is generated from.
# shellcheck disable=SC2034
if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — put the container runtime on the build machine and prove it comes
# back on its own. Everything here needs a human: a reboot, a security
# setting, a phone approving a code.
# ──────────────────────────────────────────────────────────────────────────

cd "$(dirname "${BASH_SOURCE[0]}")/.."

STATE_DIR="$PWD/state"
PROBE_IMAGE="codex-probe:local"

# build_probe_image — the Codex CLI in a container, which is all stages 4 and 5 need.
#
# `ca-certificates` is not optional and its absence is not obvious: `node:*-slim` ships no system
# trust store, Node carries its own roots so `npm install` succeeds anyway, and the Codex CLI is a
# native binary that reads the system store. Without this line the login dies on
# "error sending request for url" with working egress and nothing else to go on.
build_probe_image() {
  docker build -q -t "$PROBE_IMAGE" - <<'DOCKERFILE'
FROM node:22-slim
RUN apt-get update && apt-get install -y --no-install-recommends ca-certificates && rm -rf /var/lib/apt/lists/*
RUN npm install -g @openai/codex
DOCKERFILE
}

# codex_in_container ARGS... — a container shaped exactly like the one the Solver ships as:
# the credential lives on the host mount, and nothing is copied in from this machine.
codex_in_container() {
  docker run --rm -i -e CODEX_HOME=/state/codex -v "$STATE_DIR:/state" "$PROBE_IMAGE" "$@"
}

# mount_reaches_the_vm — whether a bind mount of STATE_DIR actually arrives inside a container.
#
# Colima mounts the home directory and the pinned external competition root. A `-v` from anywhere
# else fails silently: the container gets an empty directory rather than an error. A login written
# there is lost on `docker rm` with nothing said, which is the property stage 5 proves.
mount_reaches_the_vm() {
  local sentinel="$STATE_DIR/.mount-check"
  mkdir -p "$STATE_DIR/codex"
  date +%s > "$sentinel"
  docker run --rm -v "$STATE_DIR:/state" alpine test -f /state/.mount-check
}

TOTAL_STAGES=5

banner "Put the runtime on this machine, and prove it restarts alone"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "The runtime, on the pin"
say "Colima and the Docker CLI, at the versions this repository names, on the"
say "allocation it commits to. This part needs no decision from you."
say ""
if ! command -v colima >/dev/null 2>&1 || ! command -v docker >/dev/null 2>&1; then
  step "Installing them:  brew install colima docker"
  brew install colima docker
fi
python3 scripts/runtime.py enable-at-login || SKIPPED+=("re-run: python3 scripts/runtime.py enable-at-login")
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The login screen, and the FileVault wall"
say "A Mac that reboots to a login screen starts nothing: the VM comes up from a"
say "LaunchAgent, and a LaunchAgent runs at *user login*, not at boot."
say ""
if fdesetup status | grep -q "FileVault is On"; then
  warn "FileVault is On, so macOS refuses automatic login outright — there is no"
  warn "setting to flip. This machine cannot come back from a power cut unattended."
  say ""
  say "Three ways out, and the choice is yours rather than this script's:"
  step "Leave it. A planned reboot is fine (stage 3); an unplanned one waits for you."
  step "Turn FileVault off for the event — a real security trade on the machine that"
  note "     holds the team key, the one secret nobody can rotate. Read ADR-0012 first."
  step "Put the run on a machine with FileVault off."
  say ""
  note "Nothing here turns FileVault off for you. That decision is not a script's to make."
  SKIPPED+=("decide the FileVault trade before the event — docs/adr/0012")
else
  say "FileVault is off, so automatic login is available."
  open_url "x-apple.systempreferences:com.apple.Users-Groups-Settings.extension"
  step "Users & Groups -> Automatically log in as -> this account, then enter the password."
  note "Verified by the reboot in stage 3, not by the settings pane agreeing with you."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Prove the reboot"
say "A container with --restart unless-stopped, a real reboot, and a verdict reached"
say "by clock rather than by eye: it counts only if the container started *after*"
say "the host booted, on a machine that reached a session without you."
say ""

reboot_hint() {
  if fdesetup supportsauthrestart | grep -q true; then
    say "This Mac supports an authenticated restart, which skips the FileVault unlock"
    say "screen for this one reboot:"
    note "  sudo fdesetup authrestart"
    say ""
  fi
  step "Reboot, log back in, and re-run this wizard. It resumes here."
  SKIPPED+=("reboot, then: bash scripts/setup-runtime.sh")
}

if docker inspect restart-probe >/dev/null 2>&1; then
  outcome=0
  python3 scripts/restart_probe.py check || outcome=$?
  say ""
  case "$outcome" in
    0) note "That is the criterion this whole ticket exists for." ;;
    1) warn "The probe is left exactly as it stands. That verdict is the finding, and"
       warn "re-arming would erase the only evidence of it."
       SKIPPED+=("the container did not come back unattended — read the verdict above, then ADR-0012") ;;
    *) reboot_hint ;;
  esac
else
  step "Arming the probe now."
  python3 scripts/restart_probe.py arm || true
  say ""
  reboot_hint
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Log Codex in, inside the container"
say "The credential is minted in the container that spends it. Nothing is copied"
say "from this machine, and no browser exists in there (ADR-0011)."
say ""
if ! mount_reaches_the_vm; then
  warn "the host mount is not reaching the container — Colima mounts your home and"
  warn "the pinned external competition root; any other path arrives empty and silent."
  note "Move this repository under an allowed root and re-run. Everything below would appear to"
  note "work and then lose the login on the next docker rm."
  SKIPPED+=("move the repository under an allowed Colima mount, then re-run this wizard")
else
  step "Building the probe image."
  build_probe_image
  say ""
  say "It prints a link and a one-time code. Open the link anywhere — your phone is"
  say "fine — sign in, and enter the code. The code expires in 15 minutes."
  say ""
  codex_in_container codex login --device-auth || warn "login did not complete — re-run this stage"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Prove the login survives, and drives a completion"
say "Two things, on a container built fresh from the image with no login of its own."
say ""
step "It is already authenticated, because the credential is on the mount."
codex_in_container codex login status || SKIPPED+=("codex login status failed — re-run stage 4")
say ""
step "And it answers non-interactively, which is what the Solver's seam calls."
# --skip-git-repo-check because `codex exec` refuses to start outside a git worktree, and the
# Solver image is not one. -s read-only because this proves a completion, not a tool call.
if codex_in_container codex exec --skip-git-repo-check -s read-only \
     --output-last-message /state/last-message.txt \
     "Reply with exactly: runtime ready" >/dev/null 2>&1 && [[ -s "$STATE_DIR/last-message.txt" ]]; then
  printf '  %s✓ codex exec returned:%s %s\n' "$GREEN" "$RESET" "$(cat "$STATE_DIR/last-message.txt")"
else
  warn "codex exec returned nothing — the credential logs in but does not complete"
  SKIPPED+=("codex exec --output-last-message returned nothing usable")
fi
pause

finish
